class VamtamCallToAction extends elementorModules.frontend.handlers.Base{getDefaultSettings(){return{selectors:{btnText:".elementor-button"}}}getDefaultElements(){const e=this.getSettings("selectors");return{$btnText:this.$element.find(e.btnText)}}onInit(...e){super.onInit(...e),this.handleCtaBtnUnderlineAnimation()}handleCtaBtnUnderlineAnimation(){if(!this.$element.hasClass("vamtam-has-underline-anim"))return;const e=this.elements.$btnText.text();this.elements.$btnText.text(""),this.elements.$btnText.append('<span class="vamtam-btn-text">'+e+"</span>")}}jQuery(window).on("elementor/frontend/init",()=>{if(elementorFrontend.elementsHandler&&elementorFrontend.elementsHandler.attachHandler)elementorFrontend.elementsHandler.attachHandler("call-to-action",VamtamCallToAction);else{const e=e=>{elementorFrontend.elementsHandler.addHandler(VamtamCallToAction,{$element:e})};elementorFrontend.hooks.addAction("frontend/element_ready/call-to-action.default",e,100)}});